-- Las tablas del motor de formularios (form/form_section/question/option/
-- visibility_condition/repeater_group) NO están en db_postgres_creation.sql
-- — solo las crea GORM AutoMigrate cuando arranca la app real (main.go), lo
-- cual todavía no pasó en este punto del setup. Se crean aquí como mirror
-- best-effort de la estructura real (columnas/tipos leídos de Supabase vía
-- Composio) para poder insertar los datos ya; IF NOT EXISTS las deja intactas
-- si la app ya arrancó antes. Cuando la app arranque de verdad, su propio
-- AutoMigrate autocorrige cualquier diferencia (agrega columnas que falten)
-- — igual que ya hace con las tablas legacy, no hace falta mantener esto
-- en sync a mano.
CREATE TABLE IF NOT EXISTS salvia.form (
    id character varying(36) PRIMARY KEY DEFAULT gen_random_uuid(),
    name character varying(255) NOT NULL,
    description text NOT NULL,
    status character varying(20) NOT NULL DEFAULT 'active',
    created_at timestamptz,
    updated_at timestamptz,
    deleted_at timestamptz,
    campaign_id character varying(50)
);
CREATE TABLE IF NOT EXISTS salvia.form_section (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    form_id uuid NOT NULL,
    name character varying(255) NOT NULL,
    description text,
    "order" bigint DEFAULT 0,
    created_at timestamptz,
    updated_at timestamptz,
    deleted_at timestamptz
);
CREATE TABLE IF NOT EXISTS salvia.repeater_group (
    id character varying(36) PRIMARY KEY DEFAULT gen_random_uuid(),
    form_section_id character varying(36) NOT NULL,
    name character varying(255) NOT NULL,
    item_name character varying(100),
    "order" bigint DEFAULT 0,
    min_repetitions bigint DEFAULT 0,
    max_repetitions bigint,
    state_items character varying(255),
    created_at timestamptz,
    updated_at timestamptz,
    deleted_at timestamptz,
    add_button_label character varying(255),
    parent_repeater_group_id character varying(36)
);
CREATE TABLE IF NOT EXISTS salvia.question (
    id character varying(36) PRIMARY KEY DEFAULT gen_random_uuid(),
    form_id character varying(36) NOT NULL,
    form_section_id character varying(36) NOT NULL,
    repeater_group_id character varying(36),
    question_type character varying(50) NOT NULL,
    description text NOT NULL,
    required boolean DEFAULT false,
    state_options_path character varying(255),
    "order" bigint DEFAULT 0,
    created_at timestamptz,
    updated_at timestamptz,
    deleted_at timestamptz,
    metadata text,
    options text
);
CREATE TABLE IF NOT EXISTS salvia.option (
    id character varying(36) PRIMARY KEY DEFAULT gen_random_uuid(),
    question_id character varying(36) NOT NULL,
    label character varying(255) NOT NULL,
    value character varying(255) NOT NULL,
    "order" bigint DEFAULT 0,
    created_at timestamptz,
    updated_at timestamptz,
    deleted_at timestamptz
);
CREATE TABLE IF NOT EXISTS salvia.visibility_condition (
    id character varying(36) PRIMARY KEY DEFAULT gen_random_uuid(),
    target_type character varying(50) NOT NULL,
    target_id character varying(36) NOT NULL,
    trigger_question_id character varying(36) NOT NULL,
    trigger_state_path character varying(255),
    trigger_value character varying(255),
    operator character varying(20) NOT NULL,
    created_at timestamptz,
    updated_at timestamptz,
    trigger_option_id character varying(36)
);

